INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Worklink: another volunteer-led support for job-seekers', 'worklink-another-volunteer-led-support-for-job-seekers', '<p></p>
<div><a href="https://2.bp.blogspot.com/-bYOe15_WIuc/T-BedmMpOFI/AAAAAAAAAgI/Y2kSG6_wXKo/s1600/WORKLINK+logo.png"><img decoding="async" border="0" height="123" src="https://2.bp.blogspot.com/-bYOe15_WIuc/T-BedmMpOFI/AAAAAAAAAgI/Y2kSG6_wXKo/s320/WORKLINK+logo.png" width="320" /></a></div>
<div><span>An expanding network of volunteers is providing help to job-seekers in Dublin, </span><span>Limerick, Sligo, Athlone, Cork, Galway, and Waterford.</span></div>
<div><span>The Worklink project employs two paid staff in Dublin with most of the work being done by the volunteers.</span></div>
<div><span>Unemployed people are offered mentoring and work experience opportunities (eg through Jobbridge) as a step towards full-time employment.</span></div>
<div><span>The project has the backing of the INOU and this year Worklink won €50,000 and backroom support from Diageo through the </span><span>Arthur Guinness Fund.</span></div>
<div><span>If you live in any of the areas listed and are interested, either in volunteering or in getting support to find suitable work experience, the project is worth approaching as it has direct links with a number of companies that appreciate its aims.</span></div>
<div><span>T: 01-2916603.</span></div>
<div><b><span>W: </span></b><span lang="EN-GB"><a href="https://www.worklink.ie/"><b><span lang="EN-US">www.worklink.ie</span></b></a></span><b><span lang="EN-GB"> </span></b><b><span></span></b></div>', 'An expanding network of volunteers is providing help to job-seekers in Dublin, Limerick, Sligo, Athlone, Cork, Galway, and Waterford. The Worklink project employs two paid staff in Dublin with most of the work being done by the volunteers. Unemployed people are offered mentoring and work experience opportunities (eg through Jobbridge) as a step towards full-time', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 198, 1, '2012-06-26T11:12:00Z', '2012-06-26T11:12:00Z', '2012-06-26T11:12:00Z')
