INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Belfast unemployed centre fuelled by bar', 'belfast-unemployed-centre-fuelled-by-bar', '<p></p>
<div><a href="https://3.bp.blogspot.com/-hd1jx5pM7yM/T-BcLJHdTcI/AAAAAAAAAf8/8pT0LD2TDaw/s1600/JOHN+HEWITT+1128.JPG"><img decoding="async" border="0" height="235" src="https://3.bp.blogspot.com/-hd1jx5pM7yM/T-BcLJHdTcI/AAAAAAAAAf8/8pT0LD2TDaw/s320/JOHN+HEWITT+1128.JPG" width="320" /></a></div>
<div><i>The John Hewitt</i>, an award-winning bar in Belfast city centre, is owned by and financially supports the operations of the Belfast Unemployed Resource Centre.</div>
<div>The resource centre had always relied on an unsteady series of grants and 15 years ago decided to generate their own funds by going into business. </div>
<div>A manager runs the bar on behalf of the Resource Centre and the idea has proved a winner. </div>
<div>John Hewitt,<i> </i>the late Belfast poet and socialist opened the Resource Centre in 1983 and the bar is named in his honour. The two premises are located side-by-side on Donegall Street. </div>
<div>W: <span lang="EN-GB"><a href="https://www.thejohnhewitt.com/"><span lang="EN-US">www.thejohnhewitt.com</span></a></span></div>', 'The John Hewitt, an award-winning bar in Belfast city centre, is owned by and financially supports the operations of the Belfast Unemployed Resource Centre. The resource centre had always relied on an unsteady series of grants and 15 years ago decided to generate their own funds by going into business. A manager runs the bar', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 200, 1, '2012-06-25T08:30:00Z', '2012-06-25T08:30:00Z', '2012-06-25T08:30:00Z')
