INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Volunteers now running 3 job-seekers’ centres', 'volunteers-now-running-3-job-seekers-centres', '<p></p>
<h3>   Citizens fill in where there are no staff in West Cork</h3>
<div><a href="https://1.bp.blogspot.com/-Bz-oP7py6_A/T-BVI9ZDURI/AAAAAAAAAfo/EdfGMMsJxHc/s1600/BEST+Jobseekers+Resource+Centre+Header.jpg"><img loading="lazy" decoding="async" border="0" height="113" src="https://1.bp.blogspot.com/-Bz-oP7py6_A/T-BVI9ZDURI/AAAAAAAAAfo/EdfGMMsJxHc/s320/BEST+Jobseekers+Resource+Centre+Header.jpg" width="320" /></a></div>
<div><b><span>By Robert McNamara</span></b></div>
<div>Three community led job-seekers centres, staffed by volunteers, are currently operating in the West Cork area, with plans for three more to be opened.</div>
<div>Only for them, unemployed people in West Cork would be left to swim.</div>
<div>
<div></div>
<p>The centres which offer free advice and confidential support in Bandon, Kinsale and Clonakilty are managed by the West Cork Development Board (WCDP) and offer a &#8220;holistic&#8221; approach to job-searching. A “buddy” system operates, with volunteers assisting the job-seekers in all aspects of the process.</p></div>
<div>The centres serve a region that comprises of eight mid-size towns, which currently have approximately 10,000 people on the live register. There are no Local Employment Services Offices, or Jobs Clubs, and only 9 per cent of the territory is covered by Local Development Plans. <br /><a name=''more''></a></div>
<div>LCDP manager Fergal Conlon believes that the centres are an essential resource for those looking for work. “They are hugely important because without job-seekers’ centres, a job-seeker would have nowhere to go and no-one to get advice and support from and they’d be left on their own and isolated.&#8221;</p>
<div><a href="https://4.bp.blogspot.com/-WbgmdkaFXXk/T-rbBhVKmDI/AAAAAAAAAk4/5vyFj6i7yJE/s1600/IMG_2027.jpg"><img loading="lazy" decoding="async" border="0" height="320" src="https://4.bp.blogspot.com/-WbgmdkaFXXk/T-rbBhVKmDI/AAAAAAAAAk4/5vyFj6i7yJE/s320/IMG_2027.jpg" width="239" /></a></div>
<p></div>
<div>Karen Moroney is a volunteer at the Clonakilty centre: “We talk to people and assess what their needs are and support them through that. Some people may have been with the one employer for a long time and maybe wouldn&#8217;t know how to put a CV together, so we help them. If they want to delve in further and go through the programme that we offer, then we can do that as well”.</div>
<div>The centres mimic the approach of Citizens Information Services by allowing volunteers to deliver information and advice via IT tools.</div>
<div>&#8220;They provide volunteers at the front-line to deliver support in a complex area and they’re dealing with complicated information. So in that sense we&#8217;re trying to copy them in some ways with a job-seeking twist obviously&#8221;, said Fergal.</div>
<div>The idea for the centres grew from an existing website service by the WCDP (www. westcorkjobsupport.com) that offered a range of job-seeking tools and resources. The website proved popular, but ultimately failed to reach out to those not IT savvy .</div>
<div>Three more job-seekers’ support centres are now planned. </div>
<div>&#8220;We&#8217;re immediately looking at the towns in Macroom, Skibereen and we&#8217;ll be considering Dunmanway and Castletownbere later in the year aswell&#8221;, Fergal confirmed.</div>
<div>The centres offer a wide range of advice in areas such as rights and entitlements, career decision-making, CV and interview preparation, options and sources of training, course information, identification of job-seeking techniques through networking, publications and the internet, and development of a personal strategy for pro-active job seeking. </div>
<div>Broadband and printing services are also available at the centres.<br />And every one of the centres depends on volunteers continuing to step forward.</div>
<div>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-7Hm-Ywx7FwE/T-rbogrFhSI/AAAAAAAAAlA/i7MwvZ-q0mg/s1600/Distrib+of+empl+support+services+in+ROI+-+look+at+Co+Cork.png"><img loading="lazy" decoding="async" border="0" height="325" src="https://2.bp.blogspot.com/-7Hm-Ywx7FwE/T-rbogrFhSI/AAAAAAAAAlA/i7MwvZ-q0mg/s400/Distrib+of+empl+support+services+in+ROI+-+look+at+Co+Cork.png" width="400" /></a></td>
</tr>
<tr>
<td>
<div><i>Distribution of employment support services in the ROI. The map shows what&#8217;s available but also the gaps; for instance there was nothing between Bantry and Cork City.</i></div>
</td>
</tr>
</tbody>
</table>
<p></div>', 'Citizens fill in where there are no staff in West Cork By Robert McNamara Three community led job-seekers centres, staffed by volunteers, are currently operating in the West Cork area, with plans for three more to be opened. Only for them, unemployed people in West Cork would be left to swim. The centres which offer', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 201, 1, '2012-06-22T08:00:00Z', '2012-06-22T08:00:00Z', '2012-06-22T08:00:00Z')
