VALUES ('Robert McNamara, Journalist', 'robert-mcnamara-journalist', '<p></p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://1.bp.blogspot.com/-_7GaG94YHrg/T-BOf5e_dMI/AAAAAAAAAfM/0su_LNxHUkY/s1600/ROBERT+MCNAMARA+H&amp;S.JPG"><img loading="lazy" decoding="async" border="0" height="320" src="https://1.bp.blogspot.com/-_7GaG94YHrg/T-BOf5e_dMI/AAAAAAAAAfM/0su_LNxHUkY/s320/ROBERT+MCNAMARA+H&amp;S.JPG" width="229" /></a></td>
</tr>
<tr>
<td>Robert McNamara</td>
</tr>
</tbody>
</table>
<p></p>
<div><b><span lang="EN-GB"></span></b><span lang="EN-GB">Robert McNamara from Corbally in Limerick City, has joined Changing Ireland Community Media Ltd on a long-term work placement as a journalist.</span></div>
<div><span lang="EN-GB">He is currently studying a degree in Journalism and New Media with sociology and politics at the University of Limerick as a mature student.</span></div>
<div><span lang="EN-GB">Robert is the current sports editor at An Focal newspaper and maintains a popular indie music blog. He has a keen interest in current affairs, print journalism, publication design, old and new media. </span></div>
<div><span lang="EN-GB">Robert competes in long-distance running and can often be seen hobbling around after a marathon.</span></div>
<div><span lang="EN-GB">He hopes to graduate from UL in 2014 and pursue a career in the media industry.</span></div>
<div><b><span lang="EN-GB">E: </span></b><span lang="EN-GB"><a href="mailto:journalist@changingireland.ie"><b>journalist@changingireland.ie</b></a><b> T: 061-458090.</b></span></div>', 'Robert McNamara Robert McNamara from Corbally in Limerick City, has joined Changing Ireland Community Media Ltd on a long-term work placement as a journalist. He is currently studying a degree in Journalism and New Media with sociology and politics at the University of Limerick as a mature student. Robert is the current sports editor at', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 203, 1, '2012-06-20T08:00:00Z', '2012-06-20T08:00:00Z', '2012-06-20T08:00:00Z')
