INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('25,000 jobs possible, says John Murphy', '25000-jobs-possible-says-john-murphy', '<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-fj5nJa0rEmI/T2taNpHoMKI/AAAAAAAAAeI/mMJbYsuhXxo/s1600/Speedpak+boss+John+Murphy.JPG"><img loading="lazy" decoding="async" border="0" height="235" src="https://4.bp.blogspot.com/-fj5nJa0rEmI/T2taNpHoMKI/AAAAAAAAAeI/mMJbYsuhXxo/s320/Speedpak+boss+John+Murphy.JPG" width="320" /></a></td>
</tr>
<tr>
<td>John Murphy CEO Speedpak</td>
<td></td>
</tr>
</tbody>
</table>
<p></p>
<div><span lang="EN-GB">The EU Commission’s ‘Social Business Initiative’ reflects the value and potential the EU Commission sees in models of social enterprises and entrepreneurship right across Europe. </span></div>
<div></div>
<div><span lang="EN-GB">Social enterprises represent on average 5% of GDP in the EU but only 3% in Ireland – so we have some catching up to do. It’s estimated that if over 5 years we could reach the EU average we would create 25,000 jobs.</span></div>
<div><span lang="EN-GB"></span></div>
<p><a name=''more''></a></p>
<div><span lang="EN-GB">Giving EU-wide access to private and structural funds are very important developments for those engaging in social enterprise.</span></div>
<div></div>
<div><span lang="EN-GB">However, for the EU Commission’s initiative to have any impact nationally, it is important that the Government follows through on its commitment in the Programme for Government to explore the potential of social enterprise. </span></div>
<div></div>
<div><span lang="EN-GB">The report of the Social Enterprise (&amp; Entrepreneurship) Task Force provides a roadmap for Government. It makes key recommendations that can support the development of the sector and ultimately the creation of jobs. </span></div>
<div></div>
<div><span lang="EN-GB">Besides the need for a national policy framework for the sector the report suggests:</span></div>
<div></div>
<div><span lang="EN-GB">&#8211;<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span lang="EN-GB">A Minister of State designated to have responsibility for social enterprise. </span></div>
<div><span lang="EN-GB">&#8211;<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span lang="EN-GB">Allowing access to existing support structures and procurement frameworks.</span></div>
<div><span lang="EN-GB">&#8211;<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span lang="EN-GB">Including social clause provisions within the public and local authority. </span></div>
<div><span lang="EN-GB">&#8211;<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span lang="EN-GB">Creating a social innovation fund and </span></div>
<div><span lang="EN-GB">&#8211;<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span lang="EN-GB">Piloting a Social Impact Bond Scheme.&nbsp;</span></div>
<div></div>
<div><span lang="EN-GB">If the recommendations are followed up,<u> jobs will result – something this country badly needs.</u></span></div>
<div></div>
<div><span lang="EN-GB">* John P. Murphy is the CEO of Speedpak Ltd, an award-winning social enterprise that employs, trains and supports local long term unemployed people through its two commercial businesses; Speedpak contract packing services and Shamrock Rosettes. </span></div>
<div></div>
<div><span>Links: <a href="https://www.speedpak.ie/">www.speedpak.ie</a> and <a href="https://www.shamrockrosettes.com/">www.shamrockrosettes.com</a> </span></div>', 'John Murphy CEO Speedpak The EU Commission’s ‘Social Business Initiative’ reflects the value and potential the EU Commission sees in models of social enterprises and entrepreneurship right across Europe. Social enterprises represent on average 5% of GDP in the EU but only 3% in Ireland – so we have some catching up to do. It’s', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 207, 1, '2012-03-22T17:14:00Z', '2012-03-22T17:14:00Z', '2012-03-22T17:14:00Z')
