INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('A London Perspective for Limerick', 'a-london-perspective-for-limerick', '<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://1.bp.blogspot.com/-xq82tcn_2Sg/T2schoq921I/AAAAAAAAAdw/yE8NkO8LSTE/s1600/Michael+Pyner.png"><img loading="lazy" decoding="async" border="0" height="270" src="https://1.bp.blogspot.com/-xq82tcn_2Sg/T2schoq921I/AAAAAAAAAdw/yE8NkO8LSTE/s320/Michael+Pyner.png" width="320" /></a></td>
</tr>
<tr>
<td><i><span>Michael Pyner</span></i></td>
</tr>
</tbody>
</table>
<p>   <span>Michael Pyner </span><span>established the Shoreditch Trust in Hackney, London, in 2000 and since then it has become a multi award-winning community investment and regeneration agency.</span><br /><a name=''more''></a>     </p>
<div></div>
<div><span>From growing lettuce indoors on walls (why not?!) to training former prisoners as chefs and buying up property to rent, much to the consternation of some funders, the Shoreditch Trust has shown an eagerness to take a fresh approach to community work.&nbsp;</span></div>
<div></div>
<div><span>He shared his story along with his views on the models and the future of community and social enterprise at a seminar held in Limerick on March 8th.&nbsp;</span></div>
<div></div>
<div><span>The event was organised by </span><span>the PAUL Partnership and Limerick City Enterprise Board at which details of a new training programme for local community leaders were also announced.&nbsp;</span></div>
<div></div>
<div><span>The programme was designed with cross-border collaboration and should lead to more jobs being created in the Mid-West in social and community enterprise.</span><span></span></div>', 'Michael Pyner Michael Pyner established the Shoreditch Trust in Hackney, London, in 2000 and since then it has become a multi award-winning community investment and regeneration agency. From growing lettuce indoors on walls (why not?!) to training former prisoners as chefs and buying up property to rent, much to the consternation of some funders, the', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 208, 1, '2012-03-22T12:39:00Z', '2012-03-22T12:39:00Z', '2012-03-22T12:39:00Z')
