INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Social enterprise – has its time finally come?', 'social-enterprise-has-its-time-finally-come', '<p></p>
<div><a href="https://1.bp.blogspot.com/-6DotFUDdpso/T2sOINo257I/AAAAAAAAAdo/-8eDt_4IILg/s1600/EU_Commission.jpg"><img loading="lazy" decoding="async" border="0" height="240" src="https://1.bp.blogspot.com/-6DotFUDdpso/T2sOINo257I/AAAAAAAAAdo/-8eDt_4IILg/s320/EU_Commission.jpg" width="320" /></a></div>
<div><b><span lang="EN-GB">By Tanya Lalor and Gerard Doyle</span></b></div>
<div></div>
<div><span lang="EN-GB">Recent moves by the EU Commission on social enterprise will have a significant influence in years to come.</span></div>
<div></div>
<div><span lang="EN-GB">The Commission now sees social enterprise as being at the heart of the drive to create a more inclusive model of economic development than the current market-led one.</span></div>
<p><a name=''more''></a>     </p>
<div><span lang="EN-GB">Social enterprises are part of the wider social economy sector, which is estimated to employ over 11million workers, or 6% of the total EU workforce. However, the EU Commission acknowledges that if a number of barriers affecting social enterprises are addressed, the sector can play a more central role in developing a more inclusive economy. So it proposed a number of actions:</span></div>
<div></div>
<div><span lang="EN-GB">·<span>&nbsp; </span></span><span lang="EN-GB">Facilitating access to private funding.</span></div>
<div></div>
<div><span lang="EN-GB">·<span>&nbsp; </span></span><span lang="EN-GB">Mobilisation of EU funds for social enterprises. </span></div>
<div></div>
<div><span lang="EN-GB">·<span>&nbsp; </span></span><span lang="EN-GB">Encouraging member states to put more of the EU’s allocation of structural funds into social enterprises.</span></div>
<div></div>
<div><span lang="EN-GB">·<span>&nbsp; </span></span><span lang="EN-GB">In awarding public contracts, social enterprises should be allowed compete for work.</span><span lang="EN-GB"></span></div>
<div></div>
<div><b><span>Recent developments</span></b></div>
<div></div>
<div><span>Since the launch of the EU Commission’s ‘<i>Social Business Initiative’ </i>the following has happened:</span></div>
<div></div>
<div><span>·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span>In December 2011, a review of the Procurement Directives was announced by Commissioner for the Internal Market and Services, Michel Barnier.&nbsp; One of the aims is to ensure greater consideration for social and environmental criteria which could really provide an impetus for social enterprises in the coming years. It is hoped legislation will be forthcoming by December coming.</span></div>
<div></div>
<div><span>·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span lang="EN-GB">The Commission introduced proposals for a new ‘European Social Entrepreneurship Funds’ label so investors can easily identify funds that focus on investing in European social businesses.</span></div>
<div></div>
<div><span lang="EN-GB">·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span>Also in December 2011, Commission László Andor announced plans for </span><span lang="EN-GB">the promotion of the social economy and social enterprises through the European Social Fund. Further financial support will also be provided over the period 2014 to 2020 through the Programme for Social Change and Innovation.</span></div>
<div></div>
<div><b><span lang="EN-GB">Implications for Ireland</span></b></div>
<div></div>
<div><span lang="EN-GB">The Programme for Government has already made a commitment to promoting the development of a vibrant and effective social enterprise sector.&nbsp; This has been followed up to in the recent ‘<i>2012 Action Plan for Jobs’</i> in which the government commited to commissioning a report on the potential of social enterprise to create jobs, with a view to completion by end this year.</span></div>
<div></div>
<div>     </div>
<div><i><span lang="EN-GB">Ms Lalor and Mr Doyle work for TSA Consultancy.</span></i></div>
<p><span lang="EN-GB"></span></p>', 'By Tanya Lalor and Gerard Doyle Recent moves by the EU Commission on social enterprise will have a significant influence in years to come. The Commission now sees social enterprise as being at the heart of the drive to create a more inclusive model of economic development than the current market-led one. Social enterprises are', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 209, 1, '2012-03-22T11:38:00Z', '2012-03-22T11:38:00Z', '2012-03-22T11:38:00Z')
