INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Zumbathon – a fun way to find funds', 'zumbathon-a-fun-way-to-find-funds', '<p></p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-01qOt7ZI5yc/T2sD6hEO5WI/AAAAAAAAAdg/bj9OP_n6jLA/s1600/ZUMBATHON.jpg"><img loading="lazy" decoding="async" border="0" height="212" src="https://4.bp.blogspot.com/-01qOt7ZI5yc/T2sD6hEO5WI/AAAAAAAAAdg/bj9OP_n6jLA/s320/ZUMBATHON.jpg" width="320" /></a></td>
</tr>
<tr>
<td><i>An Cosán Zumbathon</i></td>
</tr>
</tbody>
</table>
<p>   <span>An Cosán, a women&#8217;s centre for learning, leadership and social enterprise based in Jobstown, Tallaght, have taken to some innovative ways to raise money.</span></p>
<p><span>Aisling Freeman has a voluntary fundraising role with the organisation. “We hope to do at least two fundraisers a year,” she says, “In 2011, we held a do in the Maldron Hotel which was very successful. We raised €6,000.”&nbsp;</span></p>
<p><span>Her most recent fundraising activity with the group was a Guinness World Record attempt, which took place in the National Basketball Arena in Tallaght on February 12th. </span> </p>
<div></div>
<p><a name=''more''></a><span>           </span>     </p>
<div>Dubbed ‘The zumbathon’, the attempt was to get as many people zumba-ing in one place at one time as possible.&nbsp;</div>
<div>Zumba is a latin-dance inspired workout routine that is garnering popularity throughout the nation. “I regularly take part in a Zumba class myself,” Aisling says, “It’s a great workout, a fantastic way to unwind and a lot of fun too.”</div>
<div>Adults were charged €11 to attend, while a family ticket (two adults, two children) retailed at €25. The hope was to get as many as 3,000 attendees and they managed almost 500. It was a success when fun and fundraising are measured.&nbsp;</div>
<div>“We raised about €4,000,” Aisling says, “and everyone who came had a fantastic time.” The hope now is for it to become an annual event, and that eventually the record will be broken.&nbsp;</div>
<div>“That’s the aim,” she says, “the more people hear about how much of a fun activity it is, the more people we will attract to the record attempt. ”</div>
<div>Another very successful fundraising attempt for An Cosán took place on International Woman’s Day, March 8th, when they held a lunch in the Shelbourne Hotel featuring Miriam O’Callaghan as MC and Minister Joan Burton as guest of honour.</div>', 'An Cosán Zumbathon An Cosán, a women’s centre for learning, leadership and social enterprise based in Jobstown, Tallaght, have taken to some innovative ways to raise money. Aisling Freeman has a voluntary fundraising role with the organisation. “We hope to do at least two fundraisers a year,” she says, “In 2011, we held a do', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 210, 1, '2012-03-22T11:08:00Z', '2012-03-22T11:08:00Z', '2012-03-22T11:08:00Z')
