INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Countries Warmest Centres are in Offaly', 'countries-warmest-centres-are-in-offaly', '<p>        </p>
<div><a href="https://4.bp.blogspot.com/-cz-rS4j2dUg/T2nqX0p7NsI/AAAAAAAAAdY/f32Sr9yiPiA/s1600/imgres-1.jpeg"><img decoding="async" border="0" src="https://4.bp.blogspot.com/-cz-rS4j2dUg/T2nqX0p7NsI/AAAAAAAAAdY/f32Sr9yiPiA/s1600/imgres-1.jpeg" /></a></div>
<div><span>Over the past two years, 41 community centres in Offaly were audited </span><span>&nbsp;</span><span>for energy-efficiency and a half- dozen of them have upgraded their centres through funding from the Rural Development Programme.&nbsp;</span></div>
<div><span><br /></span></div>
<div><span>Walls were dry-lined and insulated, windows replaced, better boilers installed and lighting changed. Among the areas with warmer more user-friendly community facilities now are St. Kilcormac, Coolderry, Ballykilmurray, Clonbullogue and Lusmagh.&nbsp;</span></div>
<div><span><br /></span></div>
<div><span>The Energy Audit Initiative is </span><span>&nbsp;</span><span>now closed. However, for anyone with </span><span>&nbsp;</span><span>queries about how Offaly Local Development Company conducted the audit and the repair/refurbishment scheme, contact Pauline Hoctor, OLDC, </span><span>&nbsp;</span><span>Millennium House, Main St,&nbsp;Tullamore, Co. Offaly.&nbsp;</span></div>
<div><span><br /></span></div>
<div><span>E:<a href="mailto:phoctor@offalyldc.ie">phoctor@offalyldc.ie</a> T: 057 9322 850&nbsp;</span><span><o:p></o:p></span></div>
<p></p>', 'Over the past two years, 41 community centres in Offaly were audited for energy-efficiency and a half- dozen of them have upgraded their centres through funding from the Rural Development Programme. Walls were dry-lined and insulated, windows replaced, better boilers installed and lighting changed. Among the areas with warmer more user-friendly community facilities now are', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 211, 1, '2012-03-21T14:52:00Z', '2012-03-21T14:52:00Z', '2012-03-21T14:52:00Z')
