INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Very Good News From Brussels for Communities', 'very-good-news-from-brussels-for-communities', '<p><a href="https://2.bp.blogspot.com/-BwW-hXFF2OA/T2nTf9i7bwI/AAAAAAAAAdQ/R2QTGI8B7XU/s1600/LDnet+LOGO.png"><img loading="lazy" decoding="async" border="0" height="82" src="https://2.bp.blogspot.com/-BwW-hXFF2OA/T2nTf9i7bwI/AAAAAAAAAdQ/R2QTGI8B7XU/s200/LDnet+LOGO.png" width="200" /></a></p>
<div><span>There’s good news from Brussels as more funds may begin flowing towards communities throughout Europe in two years time. </span></div>
<div><span><br /></span></div>
<div><span>The European Commission talks for the first time in its spending plans about “community-led local development” as it looks towards 2014-’20.</span></div>
<div><span><br /></span></div>
<div><span>The folk who write for LDnet want to know what this gobbly- gook phrase means, while acknowledging the Commission’s proposals mark “a turning point in favour of local development”.&nbsp;</span></div>
<p><a name=''more''></a></p>
<div><span>This is what the Commission has said for now: “(We) propose to strengthen community-led initiatives, facilitate the implementation of integrated local development strategies and formation of local action groups, based on the experience of the LEADER approach.”</span></div>
<div><span><br /></span></div>
<div><span>Will the most marginalised people in communities have any real say in how the funding is spent in their areas, nationally and across Europe? Let’s hope that local organisations are at the centre of these developments and the decision-making involved. </span></div>
<div><span><br /></span></div>
<div><span>Visit <a href="https://ldnet.eu/">ldnet.eu</a> for more. &#8211; AM&nbsp;</span></div>', 'There’s good news from Brussels as more funds may begin flowing towards communities throughout Europe in two years time. The European Commission talks for the first time in its spending plans about “community-led local development” as it looks towards 2014-’20. The folk who write for LDnet want to know what this gobbly- gook phrase means,', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 212, 1, '2012-03-21T13:15:00Z', '2012-03-21T13:15:00Z', '2012-03-21T13:15:00Z')
