INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Mary Connors is Traveller of the Year', 'mary-connors-is-traveller-of-the-year', '<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-DwOAeaLSJco/T2nLDfIqqCI/AAAAAAAAAdA/iFvY3xPG4Hk/s1600/Mary+Connors+from+New+Ross.jpg"><img loading="lazy" decoding="async" border="0" height="200" src="https://3.bp.blogspot.com/-DwOAeaLSJco/T2nLDfIqqCI/AAAAAAAAAdA/iFvY3xPG4Hk/s200/Mary+Connors+from+New+Ross.jpg" width="129" /></a></td>
</tr>
<tr>
<td><span>Mary Connors</span></td>
</tr>
</tbody>
</table>
<div><span>On December 1, 2011, Mary Connors from New Ross was presented with the overall Traveller Pride 2011 Award at a ceremony supported by ten national Traveller organisations.</span></div>
<div>
<div></div>
</div>
<div>
<div><span>She said, “I would hope that my grandchildren will not have to spend their lives fighting&nbsp; for the things that are basic human needs and that many other people take for granted such as accommodation, education and common courtesy which has been in short supply for many a Traveller.”</span></div>
<p><a name=''more''></a><span> <o:p></o:p></span></div>
<div>
<div><span><br /></span></div>
<div><span>The Wexford grandmother was honoured for her contribution to community&nbsp;and voluntary work.&nbsp;</span></div>
<div><span><br /></span></div>
<div><span>She said she looked forward to the day when “we can achieve inclusion, equality and ethnic status </span>&nbsp;<span>for Travellers in Ireland with recognition of our culture.”</span></div>
</div>
<div>
<div></div>
</div>
<div>
<div><span>The national Traveller Pride Awards are now in their third year and there was a great turnout of celebrities and television presenters for the event with credit due to the Irish Travellers Movement for organising the event.&nbsp;</span><span>Its aim&nbsp;</span>&nbsp;<span>&#8211; to promote positive images of Travellers to counteract negative media stereotyping. Pavee Point, part of the LCDP, were among ten Traveller organisations involved in the event.&nbsp;</span><span><span><br /></span></span></div>
</div>', 'Mary Connors On December 1, 2011, Mary Connors from New Ross was presented with the overall Traveller Pride 2011 Award at a ceremony supported by ten national Traveller organisations. She said, “I would hope that my grandchildren will not have to spend their lives fighting for the things that are basic human needs and that', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 213, 1, '2012-03-21T12:43:00Z', '2012-03-21T12:43:00Z', '2012-03-21T12:43:00Z')
