INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Especially for people who’ve been excluded', 'especially-for-people-whove-been-excluded', '<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-KbpB_eenzT4/T2HShKCi3UI/AAAAAAAAAbw/I9zvsylJEno/s1600/Des+%28Leargas%29.jpg"><img loading="lazy" decoding="async" border="0" height="320" src="https://4.bp.blogspot.com/-KbpB_eenzT4/T2HShKCi3UI/AAAAAAAAAbw/I9zvsylJEno/s320/Des+%28Leargas%29.jpg" width="260" /></a></td>
</tr>
<tr>
<td><span>Des Burke</span></td>
</tr>
</tbody>
</table>
<p>The European Volunteer Service (EVS) contains “specific supports to enable the participation of young people with fewer opportunities, for example as a result of disability, educational inequality, poverty or economic exclusion,” says Des Burke of Léargas.</p>
<p>The organisation funded nine young people with fewer opportunities than most to volunteer through the EVS programme in 2011. Funding is available to meet specific needs such volunteers may have and they can opt to do a short-term voluntary stint of between anything from a fortnight to two months. This may then lead to a longer-term service.</p>
<p><a href="https://leargas.ie/">W-Leargas.ie</a>.</p>
<p>For our previous posts on EVS <a href="https://www.changingireland.blogspot.com/2012/03/leargas-actively-looking-for-volunteers.html">click here</a> and <a href="https://www.changingireland.blogspot.com/2012/03/georgia-on-her-mind-evs-experience.html">here</a>.</p>', 'Des Burke The European Volunteer Service (EVS) contains “specific supports to enable the participation of young people with fewer opportunities, for example as a result of disability, educational inequality, poverty or economic exclusion,” says Des Burke of Léargas. The organisation funded nine young people with fewer opportunities than most to volunteer through the EVS programme', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 216, 1, '2012-03-15T11:31:00Z', '2012-03-15T11:31:00Z', '2012-03-15T11:31:00Z')
