INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Léargas actively looking for volunteers', 'leargas-actively-looking-for-volunteers', '<div><a href="https://3.bp.blogspot.com/-udsiQzL7D18/T1TYTfTlyrI/AAAAAAAAAao/Tq7VIWcrItw/s1600/evs.jpg"><img loading="lazy" decoding="async" border="0" height="274" src="https://3.bp.blogspot.com/-udsiQzL7D18/T1TYTfTlyrI/AAAAAAAAAao/Tq7VIWcrItw/s320/evs.jpg" width="320" /></a></div>
<div><b><span lang="EN-GB">Conor Hogan reports<o:p></o:p></span></b></div>
<div></div>
<div><span>No Irish demographic has been hit harder in the recession than the young. In fact, of the working population under 30, one in three is now unemployed – a statistic that doesn’t bear thinking about.&nbsp;</span></div>
<div></div>
<div><span>Many are hit with the uncomfortable choice of drawing the dole, working for free as an intern or emigrating. There are some interesting options, however, the European Volunteer Service (EVS) being one of them.</span><br /><a name=''more''></a><span><o:p></o:p></span></div>
<div></div>
<div><span>The EVS scheme is funded by the European Union, and open to applications from anyone between the ages of 18 and 30. “The feedback we have gotten from those who have taken part has been almost uniformly positive,”&nbsp;</span></p>
<p><span>Des Burke of Léargas, which manages European, national and international exchange and cooperation programmes in education as part of the Department of Education, tells us. “It isn’t easy, but the rewards for people who do it make it more than worthwhile.”</span></div>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-M-Hnp9ovuxM/T1TYtxrW2pI/AAAAAAAAAaw/qT6XnvKwuqE/s1600/EVS+Training+Group+Shot.png"><img loading="lazy" decoding="async" border="0" height="262" src="https://3.bp.blogspot.com/-M-Hnp9ovuxM/T1TYtxrW2pI/AAAAAAAAAaw/qT6XnvKwuqE/s400/EVS+Training+Group+Shot.png" width="400" /></a></td>
</tr>
<tr>
<td><span>An EVS training group</span></td>
</tr>
</tbody>
</table>
<div><span>In essence, the service is a volunteer swap between different nations in the EU (and some outside of it including Switzerland, Iceland and Norway). The aspiring volunteer identifies a country and volunteering position they would be interested in from an extensive database.</span></div>
<div></div>
<div><span>Generally, he/she will start their position three months after their application, and will undergo training in Swords, Co. Dublin before setting off. Transport costs are provided for, as are accommodation and meals. The volunteer also receives a small subsistence allowance and language lessons.</span><span><o:p></o:p></span></div>
<div></div>
<div><span>“Many countries in the scheme have populations with very good levels of English anyway,” Burke says, “so speaking French or German isn’t really an essential requirement really. The volunteer will also be mentored and provided with plenty of support in the host country.”</span><span><o:p></o:p></span></div>
<div></div>
<div><span>Positions available have designated themes including Arts and Culture, Media and Communications, Anti-discrimination, Disabilities, European Awareness and Rural Development. Some of the people who have participated in the scheme have ended up working in such diverse areas as helping blind people, working with the homeless, conducting art projects with theatre companies or participating in environmental or conservation projects.</span><span><o:p></o:p></span></div>
<div></div>
<div><span>The length of placement can vary anywhere from two months to a year depending on the volunteer. The funds available to administer it are relatively healthy at the moment, so Léargas are hoping more Irish people take up the opportunity to do it.</span><span><o:p></o:p></span></div>
<div></div>
<div><span>“We are currently taking more volunteers in than are going out,” Des Burke says. “85 volunteers come here as part of this compared to 35 Irish people that go abroad. It reflects the fact that Ireland is a popular destination, because of the English language and other Irish cultural aspects, but there is an opportunity for far more Irish people to take it up.”</span><span><o:p></o:p></span></div>
<div></div>
<div><i><span>For more information, contact Léargas via email at <a href="mailto:evs@leargas.ie">evs@leargas.ie.</a> Deadlines for application are on May 1st, November 1st and February 1st.<o:p></o:p></span></i></div>
<div></div>
<div><span>W: <a href="https://www.leargas.ie/">leargas.ie/</a></span><b><span lang="EN-GB"><o:p></o:p></span></b></div>', 'Conor Hogan reports No Irish demographic has been hit harder in the recession than the young. In fact, of the working population under 30, one in three is now unemployed – a statistic that doesn’t bear thinking about. Many are hit with the uncomfortable choice of drawing the dole, working for free as an intern', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 221, 1, '2012-03-05T15:22:00Z', '2012-03-05T15:22:00Z', '2012-03-05T15:22:00Z')
