INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('The pipes are calling to promote a thriving industry', 'the-pipes-are-calling-to-promote-a-thriving-industry', '<p></p>
<div><a href="https://1.bp.blogspot.com/-7jZXx1oHWKc/TyrC9SGA4EI/AAAAAAAAAag/zXLWfp8EH84/s1600/uilleann_masterset1.jpg"><img loading="lazy" decoding="async" border="0" height="240" src="https://1.bp.blogspot.com/-7jZXx1oHWKc/TyrC9SGA4EI/AAAAAAAAAag/zXLWfp8EH84/s320/uilleann_masterset1.jpg" width="320" /></a></div>
<p></p>
<div><span>While other sectors may be suffering,&nbsp; one that certainly hasn’t been affected by the recession is Uilleann Pipe making.</span><span>&nbsp;</span><span>The national bagpipe of Ireland is one of the most complicated instruments in the world to build, usually taking a master craftsman somewhere in the region of 400 hours from start to finish.</span></div>
<div></div>
<div><span>The waiting list for someone to get their hands on a set, which can retail anywhere from&nbsp; €7,000 to €20,000, is often more than seven years.&nbsp;</span><span>Ireland currently commands only 20% of this €7million-a-year industry, so the possibility of expansion, and the creation of more jobs, is enormous.</span></div>
<div><span></span></div>
<div></div>
<div><span><span>&nbsp;</span> </span><br /><span>To aid this possibility, Fingal LEADER Partnership and Na Piobairi Uilleann have teamed up to provide a three year course in Art of Uilleann Pipe Making.</span><span>&nbsp;</span><span>The comprehensive programme will cover all aspects of the trade, including basic engineering, fine precious metal mork, the history and evolution of the instrument, as well as how to run a practicing business.</span></div>
<div><span></span></div>
<div></div>
<div><span>It begins this year, and it is aimed that by the end of the course each student will have produced two full and high standard sets of pipes.</span><span> </span></div>
<p><span></span></p>', 'While other sectors may be suffering, one that certainly hasn’t been affected by the recession is Uilleann Pipe making. The national bagpipe of Ireland is one of the most complicated instruments in the world to build, usually taking a master craftsman somewhere in the region of 400 hours from start to finish. The waiting list for', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 222, 1, '2012-02-02T17:20:00Z', '2012-02-02T17:20:00Z', '2012-02-02T17:20:00Z')
