INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('When David meets Dermot', 'when-david-meets-dermot', '<p>        </p>
<div><a href="https://2.bp.blogspot.com/-WYvhsS7XbiY/TyFeDXSH6gI/AAAAAAAAAaQ/WxEudY02d5w/s1600/203.jpg"><img loading="lazy" decoding="async" border="0" height="242" src="https://2.bp.blogspot.com/-WYvhsS7XbiY/TyFeDXSH6gI/AAAAAAAAAaQ/WxEudY02d5w/s400/203.jpg" width="400" /></a></div>
<div><span>&#8216;Dublin Valentines&#8217; is&nbsp;an annual public conversation between playwright and poet Dermot Bolger and well known Dublin writers, presented by axis in association with Ballymun Whitehall Area Partnership and the North Dublin Chamber of Commerce.&nbsp;</span><span>This year his guest is David McWilliams, the leading economic commentator.</span></div>
<p><a name=''more''></a></p>
<div><span>The Irish Independent columnist was among the first to see that the Irish boom for what it was, merely a credit bubble, and accurately predicted that it would end in a monumental crash with bank failures, negative equity, rising unemployment and emigration.</span></div>
<div></div>
<div><a href="https://2.bp.blogspot.com/-x1oQReR21lQ/TyFe5EgcJkI/AAAAAAAAAaY/ZyVdIwdKVkw/s1600/201.jpg"><img loading="lazy" decoding="async" border="0" height="200" src="https://2.bp.blogspot.com/-x1oQReR21lQ/TyFe5EgcJkI/AAAAAAAAAaY/ZyVdIwdKVkw/s200/201.jpg" width="112" /></a><span>The author of such acclaimed bestsellers as &#8216;The Pope&#8217;s Children&#8217;, &#8216;The Generation Game&#8217; and &#8216;Follow the Money&#8217;, McWilliams will discuss the journey Ireland has gone through over the past two decades &#8211; and its likely journey in the decade to come &#8211; in a conversation that will be thrown open for the audience to actively participate in.<o:p></o:p></span></div>
<div></div>
<div><span><i>The event will take place on the 9th of February at 8pm. Tickets can be booked by visiting the website <a href="https://www.axis-ballymun.ie/">www.axis-ballymun.ie</a> or by calling 01 883 2100<span>.</span></i></span><span><o:p></o:p></span></div>
<p></p>', '‘Dublin Valentines’ is an annual public conversation between playwright and poet Dermot Bolger and well known Dublin writers, presented by axis in association with Ballymun Whitehall Area Partnership and the North Dublin Chamber of Commerce. This year his guest is David McWilliams, the leading economic commentator. The Irish Independent columnist was among the first to see that', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 223, 1, '2012-01-26T14:17:00Z', '2012-01-26T14:17:00Z', '2012-01-26T14:17:00Z')
