INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Wexford scheme has warmed 2500 homes & created jobs', 'wexford-scheme-has-warmed-2500-homes-created-jobs', '<div>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-RvXX3nsUMug/TuiLyv-wawI/AAAAAAAAAZA/GlOr8kMxtU0/s1600/WLDs+Warm+Scheem.jpg"><img loading="lazy" decoding="async" border="0" height="240" src="https://4.bp.blogspot.com/-RvXX3nsUMug/TuiLyv-wawI/AAAAAAAAAZA/GlOr8kMxtU0/s320/WLDs+Warm+Scheem.jpg" width="320" /></a></td>
</tr>
<tr>
<td><span>Wexford Local Development</span></td>
</tr>
</tbody>
</table>
<div><span><b>By Allen Meagher</b></span></p>
<p><span>Around ten Local Development Companies (LDCs) are delivering the Better Energy Homes Scheme around the country along with 20 other community-based organisations.</span></div>
<div><span><span>&nbsp;</span><br /></span><span>In Wexford, it’s been such a success that Wexford Local Development (WLD) were invited to showcase their work at an OECD/Pobal conference held in Dublin in October to examine local responses to long-term unemployment.</span></div>
<p><a name=''more''></a></p>
<div><span>They’ve made winters warmer for 2500 households, created a half-dozen full-time jobs and train 25 people at a time (formerly long-term unemployed) in a jobs growth area.&nbsp;</span><span>If you qualify for the fuel allowance, own your own home and it was built before 2002, you qualify for WLD’s retrofitting scheme.</span></div>
<div><span><span>&nbsp;</span><br /></span><span>The Warm Project surveys a home to see what energy efficiency measures are needed and can then step in with attic insulation, cavity wall insulation, draught proofing of doors and windows, installs lagging jackets, low energy light bulbs and provides energy advice to the householders.<o:p></o:p></span></p>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-b_UH2ZL3QDQ/TuiOqgINvrI/AAAAAAAAAZI/L85q270hIfQ/s1600/Speirs+Ed+%2526+Brian+Keogh+OECD.jpg"><img loading="lazy" decoding="async" border="0" height="213" src="https://2.bp.blogspot.com/-b_UH2ZL3QDQ/TuiOqgINvrI/AAAAAAAAAZI/L85q270hIfQ/s320/Speirs+Ed+%2526+Brian+Keogh+OECD.jpg" width="320" /></a></td>
</tr>
<tr>
<td><span>Brian Kehoe</span></td>
</tr>
</tbody>
</table>
<p><span>Brian Kehoe, CEO of WLD, explained to people who visited his exhibition stand at the OECD/Pobal conference that nobody is displaced by the work since it delivers warmer homes to people who could not afford to pay for it themselves.</span><br /><span><span>&nbsp;</span><br /></span><span>“A lot of the people who apply are elderly, long-term unemployed, or have disabilities, exactly the kind of people we want to support.”</span><br /><span><span>&nbsp;</span><br /></span><span>“If one person gets it done, a neighbour is likely to give us a call. And local social welfare offices help in getting the word out too,” he said.</span><br /><span><span>&nbsp;</span><br /></span><span>A study some years earlier found many people, particularly elderly, suffered health problems due to draughty and damp houses.&nbsp;</span><span>This Warm Project addresses the issue.&nbsp;</span><span>All participants on the project receive FETAC accredited training in “Installing Thermal Insulation” and also receive training in Health &amp; Safety, Manual Handling, Safe Pass etc., and also received industry recognised training in cavity wall insulation.</span></p>
<p><span>WLD would “embrace” the opportunity to up-skill its workforce and get them working on the installation of solar panels, renewable energy heating systems, rain water harvesting systems and external wall insulation.</span><br /><span><span>&nbsp;</span><br /></span><span>The scheme is managed by WLD, working in partnership with the Sustainable Energy Authority of Ireland, FÁS and other partners such as the ESB. Funding from SEAI for 2011 was approximately €520,000.</span><span><br /></span><span>The Warm Project is an important part of WLD’s labour market strategy under the LCDP.</span><span><br /></span><span><span>&nbsp;</span></span><br /><span><a href="https://www.wld.ie/">www.wld.ie</a></span>    </div>
</div>', 'Wexford Local Development By Allen Meagher Around ten Local Development Companies (LDCs) are delivering the Better Energy Homes Scheme around the country along with 20 other community-based organisations. In Wexford, it’s been such a success that Wexford Local Development (WLD) were invited to showcase their work at an OECD/Pobal conference held in Dublin in October', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 228, 1, '2011-12-14T11:46:00Z', '2011-12-14T11:46:00Z', '2011-12-14T11:46:00Z')
