INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Tipp parish targets energy waste to spur rural economy', 'tipp-parish-targets-energy-waste-to-spur-rural-economy', '<p>        </p>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-n-bHuQp8iyM/TuY24zrPu0I/AAAAAAAAAYw/rs6ZDsa86P8/s1600/TIPP+ENERGY+con+julie+presentation+2.JPG"><img loading="lazy" decoding="async" border="0" height="213" src="https://4.bp.blogspot.com/-n-bHuQp8iyM/TuY24zrPu0I/AAAAAAAAAYw/rs6ZDsa86P8/s400/TIPP+ENERGY+con+julie+presentation+2.JPG" width="400" /></a></td>
</tr>
<tr>
<td><span>North Tipperary Energy Presentation</span></td>
</tr>
</tbody>
</table>
<p></p>
<div><b><span>By Allen Meagher</span></b><span><br /></span><span><span>&nbsp;</span></span></div>
<div><span>An energy audit by community volunteers and development workers has found that a parish in County Tipperary spent over €1million last year to heat and power its 400 households<b>.&nbsp;</b></span></div>
<div></div>
<div><span>Thirty homes in the area had no insulation whatsoever while others were poorly insulated and were difficult, not to mind expensive, to heat. Much of the housing stock in the area dates back to before 1920.</span></div>
<p><a name=''more''></a></p>
<div><span><span>&nbsp;</span></span><span>“Cutting energy use by 25% would be the equivalent of a €250,000 investment. What are the chances of a company investing that much in a small local area in the current climate?” asked local development worker Gearóid Fitzgibbon.</span></div>
<div></div>
<div><span>His company North Tipperary LEADER Partnership and the self-styled Drombane Energy Team, hopes the local community (pop. 1000) see the savings to be made and invest in retrofitting and insulating their homes.<b>&nbsp;</b></span><span>If so, locals will get the work and phase 2 of the project will be off the ground.</span><span> </span><span>The unique audit, available online (</span><span><span><a href="https://on.fb.me/drombanenrg">on.fb.me/drombanenrg</a></span></span><span>) raised awareness about the existence of grants from the Sustainable Energy Authority of Ireland (SEAI).</span></div>
<div></div>
<div><span>Nine in every ten households in the rural district were informed they qualified for grant assistance for energy improvements: 82% for partial grants, 13% for the full Warmer Homes Scheme Grant. The house-to-house survey was carried out by teams of volunteers from Drombane/Upperchurch using a mapping system designed by the local GAA club. </span><span><o:p></o:p></span></div>
<div></div>
<div><span>The combined voluntary efforts were equal to employing a full time community worker for eight months. There was a very high response rate of 87% (350 out of 400 homes) and the finished report was launched in Drombane in October by SEAI boss Professor Owen Lewis.</span><span> </span><span>According to local organiser Con Harrington: “Small communities like ours must take a self-help approach, and not wait on state initiatives. Local people know what is best for their locality. If they take the first steps, state agencies will come on stream.”</span><span><o:p></o:p></span></div>
<div></div>
<div><span>One of the key partners on the project, Seamus Hoyne, manager of Tipperary Energy Agency (TEA) said: “In the current climate, money spent on conserving energy offers one of the best returns on investment because you make long-term savings.”</span><span><o:p></o:p></span></div>
<div></div>
<div><span>Mr Fitzgibbon (also chairperson of Changing Ireland Community Media Ltd) has worked with others on the project for nearly two years: “This project began with the question ‘What can we do to get something going in our community?’ In an age of energy scarcity and financial instability, it’s inspiring to see a community working to come up with its own answers.<b><o:p></o:p></b></span></div>
<div></div>
<div><b><span>“</span></b><span>This survey has given us the data from which to launch Phase 2 of the Project – getting local people to invest and draw down grants, and getting the work done.”</span></div>
<div></div>
<div><span>The official launch in Drombane Hall came with a half-day information and advice clinic where staff from TEA gave householders confidential feedback one-to-one on their individual surveys. They also got a chance to discuss options with certified energy and retrofit companies.</span><span><br /></span><span><o:p></o:p></span></div>
<p></p>', 'North Tipperary Energy Presentation By Allen Meagher An energy audit by community volunteers and development workers has found that a parish in County Tipperary spent over €1million last year to heat and power its 400 households. Thirty homes in the area had no insulation whatsoever while others were poorly insulated and were difficult, not to', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 230, 1, '2011-12-12T17:20:00Z', '2011-12-12T17:20:00Z', '2011-12-12T17:20:00Z')
