INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Country will be clean as a whistle shortly', 'country-will-be-clean-as-a-whistle-shortly', '<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-99As6-1jnys/Tt9OZwZ-q0I/AAAAAAAAAYE/AfI_wYJqu-s/s1600/scrap.jpg"><img loading="lazy" decoding="async" border="0" height="203" src="https://2.bp.blogspot.com/-99As6-1jnys/Tt9OZwZ-q0I/AAAAAAAAAYE/AfI_wYJqu-s/s320/scrap.jpg" width="320" /></a></td>
</tr>
<tr>
<td>A scrap metal collection </td>
</tr>
</tbody>
</table>
<p>  </p>
<div>  </div>
<div><span><b><span lang="EN-US">&#8211; Communities hoovering up scrap metal to raise funds</span></b></span><span lang="EN-US"> </span></div>
<p><span lang="EN-US"> </span></p>
<div><span lang="EN-US">Keeping a local community organisation or sports club going can be a costly affair and many took to collecting scrap metal this year to raise money. GAA clubs led the way and the idea spread </span><span lang="EN-US">like wildfire because donating costs nothing for local residents and it’s financially rewarding for the clubs.</span></div>
<div></div>
<div><span lang="EN-US">Steel, for instance, has seen its value shoot up from €30 to €220 per tonne in less than 12 months. Portmarnock Community School collected scrap to raise funds for a project in Lesotho. Meelin GAA Club in Co. Cork also jumped on the idea. So too did Castleisland Soccer Club. The list goes on.</span></div>
<div></div>
<div><span lang="EN-US">The first to notice the skyrocketing prices were criminal gangs and across the country they’ve stolen everything from beerkegs to bronzeworks. But in Donegal for instance, it is the GAA that is doing best from the rising prices by holding ‘Scrap Saturday’ collections.</span></div>
<p><a name=''more''></a></p>
<div><span lang="EN-US">&nbsp;</span><span lang="EN-US">Buncrana GAA chairman Paul McGonigle told the ‘Donegal Democrat’ that members were much happier collecting scrap than “traipsing around in the snow” to sell tickets for the Christmas draw, their traditional fund-raiser. Travel 383 kilometres south and it’s no different.</span></div>
<div></div>
<div><span lang="EN-US">“It has become a common enough way of fundraising,” Alan Shire of Fedamore GAA Club in Co. Limerick told us. “Knockainey National School, for instance, raised over €20,000.”</span></div>
<div><span lang="EN-US">His club were hoping for even a quarter of that amount, but they too found their expectations were exceeded and Fedamore brought in over €7,000.</span></div>
<div></div>
<div><span lang="EN-US">Such a collection isn’t without its hazards, however. Criminal gangs have in the past stolen the goods after a collection. “You could say that schemes like this might draw trouble onto ourselves,” Alan said, “but the benefits outweigh the cons.”</span></div>
<div></div>
<div><span lang="EN-US">Another obstacle for a time was GAA headquarters which initially discouraged the practice. In February, it wrote to clubs nationwide pointing out that scrap metal collections are not covered by the association’s liability insurance. Furthermore, the letter said that GAA properties should not be used “under any circumstance” for storing collected metal.</span></div>
<div></div>
<div><span lang="EN-US">In Donegal, the local county council insisted that the clubs c</span><span lang="EN-US">omply with the Waste Management Act.</span><span lang="EN-US"> Fedamore, however, made sure that everything was above board before their collection on November 26th.</span></div>
<div></div>
<div><span lang="EN-US"><span>&nbsp;</span>“We checked with the County Council, the Gardai and the County Board and we were approved,” Alan said. “We found that as long as you go with a licensed recycler and you manage to get rid of it on the day, everything is fine.”</span></div>
<div></div>
<div><span lang="EN-US">They collected everything from old cookers, ironing boards, radiators, unwanted cars, corrugated iron, batteries and worn saucepans and to drink cans – things that most people would only throw out or bring to a recycling plant anyway. </span></div>
<div><span lang="EN-US"><span>&nbsp;</span></span></div>
<div><span lang="EN-US">By pure coincidence, November 19-27<sup>th</sup> marked European Week for Waste Reduction.</span><span lang="EN-US"></span></div>', 'A scrap metal collection – Communities hoovering up scrap metal to raise funds Keeping a local community organisation or sports club going can be a costly affair and many took to collecting scrap metal this year to raise money. GAA clubs led the way and the idea spread like wildfire because donating costs nothing for', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 233, 1, '2011-12-07T11:37:00Z', '2011-12-07T11:37:00Z', '2011-12-07T11:37:00Z')
