INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('International local development perspectives', 'international-local-development-perspectives', '<p>  </p>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://1.bp.blogspot.com/-2eOiRh1ranM/Tt9KgEqdNiI/AAAAAAAAAX8/ZFspW1wtQJw/s1600/ldnet.gif"><img loading="lazy" decoding="async" border="0" height="82" src="https://1.bp.blogspot.com/-2eOiRh1ranM/Tt9KgEqdNiI/AAAAAAAAAX8/ZFspW1wtQJw/s200/ldnet.gif" width="200" /></a></td>
</tr>
<tr>
<td>LDnet.eu</td>
</tr>
</tbody>
</table>
<div><span lang="EN-US">A new website called ‘LDnet’ focuses on “local development” work across Europe and further afield. The site is being added to all the time and includes an up-to-date article on local development in Ireland.</span></div>
<div></div>
<div><span lang="EN-US">It looks at a new pilot project recently launched in six US cities by the Obama administration called ‘Strong Cities, Strong Communities’. It also examines the pros and cons of British prime Minister David Cameron&#8217;s ‘Big Society’ approach to supporting communities, and much more.</span></div>
<div></div>
<div><b><span lang="EN-US">W: <a href="https://ldnet.eu/">ldnet.eu</a></span></b></div>', 'LDnet.eu A new website called ‘LDnet’ focuses on “local development” work across Europe and further afield. The site is being added to all the time and includes an up-to-date article on local development in Ireland. It looks at a new pilot project recently launched in six US cities by the Obama administration called ‘Strong Cities,', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 234, 1, '2011-12-07T11:17:00Z', '2011-12-07T11:17:00Z', '2011-12-07T11:17:00Z')
