INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('15,000 employed and 70,000 trained', '15000-employed-and-70000-trained-2', '<p>  </p>
<div><span lang="EN-US">&#8211; Survey of local development companies indicates</span></div>
<div><span lang="EN-US"><span>&nbsp;</span></span></div>
<div><a href="https://2.bp.blogspot.com/-7f-sEyqrbxk/Tt8_vefimlI/AAAAAAAAAX0/jQav7Hvwh7c/s1600/ildn+logo+%25281%2529.jpg"><img loading="lazy" decoding="async" border="0" height="301" src="https://2.bp.blogspot.com/-7f-sEyqrbxk/Tt8_vefimlI/AAAAAAAAAX0/jQav7Hvwh7c/s320/ildn+logo+%25281%2529.jpg" width="320" /></a></div>
<div><span lang="EN-US"><span></span></span><span lang="EN-US">Over an 18-month period, Local Development Companies (LDCs) directly supported an estimated 15,000 people to find their way back into paid work, placed around 70,000 people on training courses and provided support to about 10,000 small business start-ups. </span><span lang="EN-US">Many if not most of these people were long-term unemployed.</span>  </div>
<div><span lang="EN-US"><span>&nbsp;</span></span></div>
<div><span lang="EN-US">The </span><span lang="EN-US">Irish Local Development Network (ILDN) </span><span lang="EN-US">has just published the results of a survey for 2010 and the first six months of this year. The survey covered </span><span lang="EN-US">just over half (27 out of 51) the LDCs in the country and our headline </span><span lang="EN-US">figures are based on a doubling of the numbers. The actual national impact may be slightly lower or indeed higher.</span></div>
<p><a name=''more''></a></p>
<div><span lang="EN-US"><span>&nbsp;</span></span><span lang="EN-US">Of the 27 companies that took part in the survey, they supported 7,341 to secure jobs and found training places for 35,006 people and 5,175 businesses were set up with their assistance. For the first time, the full range of impacts delivered by LDCs – taking into account the myriad of national programmes they deliver – has been measured.</span>  </div>
<div><span lang="EN-US"><span>&nbsp;</span></span></div>
<div><span lang="EN-US">“It gives a company-wide picture of the impact and effectiveness of what local development companies are doing on the ground to support their communities,” said the ILDN’s Brian Carty. LDCs manage the local delivery of up to 18 funded national programmes in their areas nationwide and the survey covers work conducted under the LCDP, Rural Development Programme, Tus, Rural Social Scheme, etc.</span></div>
<div><span lang="EN-US"><span>&nbsp;</span></span></div>
<div><span lang="EN-US">The Local and Community Development Programme for instance invests 80% of its resources – through the LDCs &#8211;<span>&nbsp; </span>into helping long-term unemployed people, by supporting them to return to work and training, set up businesses or indeed find work for the first time.</span></div>
<div><span lang="EN-US"><span>&nbsp;</span></span></div>
<div><span lang="EN-US">Meanwhile, under the Tus work placement programme, the 27</span><span lang="EN-US"> companies will deliver places for 2,118 unemployed people this year. One-by-one, these people are being introduced to and successfully placed with voluntary and community groups in their local areas. The target is to have 5,000 people placed nationwide through Tus by year’s end. </span><span lang="EN-US"></span></div>
<div><i><span lang="EN-US"><span>&nbsp;</span></span></i></div>
<div><i><b><span lang="EN-US">Note</span></b><span lang="EN-US">: In relation to business start-ups, the survey also found the 27 LDCs supported a further 3,532 businesses at local level through the Back to Work Education Allowance Scheme and the Short-Term Enterprise Allowance Scheme.</span></i></div>', '– Survey of local development companies indicates Over an 18-month period, Local Development Companies (LDCs) directly supported an estimated 15,000 people to find their way back into paid work, placed around 70,000 people on training courses and provided support to about 10,000 small business start-ups. Many if not most of these people were long-term', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 235, 1, '2011-12-07T10:33:00Z', '2011-12-07T10:33:00Z', '2011-12-07T10:33:00Z')
