INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('County’s First Gay Visibilty Week', 'countys-first-gay-visibilty-week', '<p>  </p>
<div><a href="https://4.bp.blogspot.com/-EPBH5hVEVs4/Tt87CQF3A2I/AAAAAAAAAXs/XT1sxmJ7z28/s1600/GayWexford-logo.jpg"><img loading="lazy" decoding="async" border="0" height="307" src="https://4.bp.blogspot.com/-EPBH5hVEVs4/Tt87CQF3A2I/AAAAAAAAAXs/XT1sxmJ7z28/s320/GayWexford-logo.jpg" width="320" /></a></div>
<div><span>Lesbian, Gay, Bisexual and Transgender Visibility Week was launched on November 14 in Wexford – the first of it’s kind in the county. It was organised by ‘Gay Wexford’ and supported by LGBT Diversity and Wexford Local Development.</span></div>
<p></p>
<div><span>Events included a ‘liberating party’ celebrating LGBT pride, a lecture about Transgender Awareness, a slideshow presentation of the Irish Queer Archive, a Civil Partnership information seminar and a screening of the Hilary Swank movie ‘Boys Don’t Cry’.</span></div>', 'Lesbian, Gay, Bisexual and Transgender Visibility Week was launched on November 14 in Wexford – the first of it’s kind in the county. It was organised by ‘Gay Wexford’ and supported by LGBT Diversity and Wexford Local Development. Events included a ‘liberating party’ celebrating LGBT pride, a lecture about Transgender Awareness, a slideshow presentation of', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 236, 1, '2011-12-07T10:10:00Z', '2011-12-07T10:10:00Z', '2011-12-07T10:10:00Z')
